import {distanceFieldCookVersion,distanceFieldCookDirectory,distanceFieldCookManifest,distanceFieldCookMaxBytes,distanceFieldGeometryHash,decodeDistanceField,distanceFieldExpectedResolution} from './mesh-distance-field-codec.js';

let source=null;
export const setDistanceFieldCookedSource=value=>{source=value;};
export const currentDistanceFieldCookedSource=()=>source;
export async function readDistanceFieldCookedResponse(response,{maximumBytes,signal}={}){
 if(!Number.isSafeInteger(maximumBytes)||maximumBytes<1)throw Error('거리장 읽기 예산 오류');signal?.throwIfAborted();const declared=Number(response.headers?.get('Content-Length'));if(declared>maximumBytes)throw Error('거리장 응답이 읽기 예산을 넘었어요.');
 if(!response.body?.getReader){const bytes=await response.arrayBuffer();if(bytes.byteLength>maximumBytes)throw Error('거리장 응답이 읽기 예산을 넘었어요.');return bytes;}
 const reader=response.body.getReader(),chunks=[];let size=0,done=false;try{while(true){signal?.throwIfAborted();const part=await reader.read();if(part.done){done=true;break;}size+=part.value.byteLength;if(size>maximumBytes)throw Error('거리장 응답이 읽기 예산을 넘었어요.');chunks.push(part.value);}const bytes=new Uint8Array(size);let at=0;for(const part of chunks){bytes.set(part,at);at+=part.length;}return bytes;}finally{if(!done)await reader.cancel().catch(()=>{});reader.releaseLock();}
}
export function createDistanceFieldCookedSource(read,{lookup}={}){
 let index;
 async function manifest(){
  if(!index)index=(async()=>{const bytes=await read(distanceFieldCookManifest,{maximumBytes:4*1024*1024});if(bytes.byteLength>4*1024*1024)throw Error('거리장 쿠킹 목록 크기 오류');const value=JSON.parse(new TextDecoder().decode(bytes));if(value?.version!==distanceFieldCookVersion||!Array.isArray(value.fields))throw Error('거리장 쿠킹 목록 형식 오류');const rows=new Map();for(const f of value.fields){if(!/^[a-f0-9]{64}$/.test(f.geometry)||!Number.isInteger(f.resolution)||(f.resolution!==0&&(f.resolution<8||f.resolution>64))||!Number.isInteger(f.bytes)||f.bytes<16||f.bytes>distanceFieldCookMaxBytes||!/^[a-f0-9]{64}$/.test(f.sha256)||f.path!==distanceFieldCookDirectory+'/'+f.sha256+'.bin')throw Error('거리장 쿠킹 목록 항목 오류');const key=f.geometry+':'+f.resolution;if(rows.has(key))throw Error('거리장 쿠킹 목록 중복');rows.set(key,f);}return rows;})();return index;
 }
 return {reader(){const state={hits:0,misses:0,rejected:0,bytesRead:0,lastError:null};return{state,async load(vertices,options){const {signal}=options;signal?.throwIfAborted();try{const geometry=await distanceFieldGeometryHash(vertices);signal?.throwIfAborted();let candidate;if(lookup){let expected;try{expected=distanceFieldExpectedResolution(vertices,options);}catch(error){if(!options.preferAnalytic)throw error;expected=0;}candidate=await lookup(geometry,expected,options);if(candidate?.resolution===0&&!options.preferAnalytic)candidate=null;if(candidate&&(candidate.geometry!==geometry||!Number.isInteger(candidate.bytes)||candidate.bytes<16||candidate.bytes>distanceFieldCookMaxBytes||!/^[a-f0-9]{64}$/.test(candidate.sha256)||candidate.path!==distanceFieldCookDirectory+'/'+candidate.sha256+'.bin'||!Number.isInteger(candidate.resolution)||(candidate.resolution!==0&&(candidate.resolution<8||candidate.resolution>64))))throw Error('거리장 캐시 항목 오류');}else{const rows=await manifest();signal?.throwIfAborted();candidate=options.preferAnalytic&&rows.get(geometry+':0');if(!candidate)candidate=rows.get(geometry+':'+distanceFieldExpectedResolution(vertices,options));}if(!candidate){state.misses++;return null;}const bytes=await read(candidate.path,{signal,maximumBytes:candidate.bytes,candidate});signal?.throwIfAborted();state.bytesRead+=bytes.byteLength;if(bytes.byteLength!==candidate.bytes)throw Error('거리장 쿠킹 파일 길이가 달라요.');const hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes)),v=>v.toString(16).padStart(2,'0')).join('');signal?.throwIfAborted();if(hash!==candidate.sha256)throw Error('거리장 쿠킹 파일 지문이 달라요.');const field=decodeDistanceField(bytes,geometry);if(field.resolution!==candidate.resolution||field.bytes>options.byteBudget)throw Error('거리장 쿠킹 해상도나 예산이 달라요.');field.requestedResolution=options.resolution;state.hits++;return field;}catch(error){if(signal?.aborted)throw signal.reason;state.rejected++;state.lastError=String(error.message).slice(0,240);return null;}}};}};
}
